// gt_embed: turns binary files into a C++ source with a lookup table.
//
//   gt_embed <out.cpp> <namespace> <symbol> <key>=<file> [<key>=<file> ...]
//   gt_embed <out.cpp> <namespace> <symbol> @<list>   (one key=file per line; no command-line limit)
//
// The generated file defines
//   namespace <ns> { struct EmbeddedFile { const char* key; const unsigned char* data; unsigned long long size; };
//                    extern const EmbeddedFile <symbol>[]; extern const unsigned long long <symbol>Count; }
// Data arrays are 16-byte aligned so SPIR-V / DXIL blobs can be used in place.
#include <cstdio>
#include <fstream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>

int main(int argc, char** argv) {
    if (argc < 4) {
        std::fprintf(stderr, "usage: %s <out.cpp> <namespace> <symbol> [key=file ...]\n", argv[0]);
        return 2;
    }
    const std::string outPath = argv[1];
    const std::string ns = argv[2];
    const std::string symbol = argv[3];

    std::ostringstream out;
    out << "// Generated by gt_embed — do not edit.\n#include <cstddef>\n\nnamespace " << ns << " {\n";
    out << "struct EmbeddedFile { const char* key; const unsigned char* data; unsigned long long size; };\n";
    out << "namespace {\n";
    std::vector<std::pair<std::string, std::size_t>> entries;
    std::vector<std::string> args;
    for (int i = 4; i < argc; ++i) {
        if (argv[i][0] != '@') {
            args.emplace_back(argv[i]);
            continue;
        }
        std::ifstream list(argv[i] + 1);
        if (!list) {
            std::fprintf(stderr, "gt_embed: cannot open list '%s'\n", argv[i] + 1);
            return 1;
        }
        for (std::string line; std::getline(list, line);) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (!line.empty()) args.push_back(line);
        }
    }
    for (const std::string& arg : args) {
        auto eq = arg.find('=');
        if (eq == std::string::npos) {
            std::fprintf(stderr, "gt_embed: bad argument '%s'\n", arg.c_str());
            return 2;
        }
        std::string key = arg.substr(0, eq);
        std::string file = arg.substr(eq + 1);
        std::ifstream in(file, std::ios::binary);
        if (!in) {
            std::fprintf(stderr, "gt_embed: cannot open '%s'\n", file.c_str());
            return 1;
        }
        std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
        out << "alignas(16) const unsigned char d" << entries.size() << "[] = {";
        for (std::size_t b = 0; b < bytes.size(); ++b) {
            if (b % 24 == 0) out << "\n";
            out << static_cast<unsigned>(bytes[b]) << ",";
        }
        out << "0};\n"; // trailing NUL makes text blobs (GLSL) usable as C strings
        entries.emplace_back(key, bytes.size());
    }
    out << "} // namespace\n\n";
    out << "extern const EmbeddedFile " << symbol << "[];\n";
    out << "extern const unsigned long long " << symbol << "Count;\n";
    out << "const EmbeddedFile " << symbol << "[] = {\n";
    for (std::size_t i = 0; i < entries.size(); ++i)
        out << "    {\"" << entries[i].first << "\", d" << i << ", " << entries[i].second << "ULL},\n";
    if (entries.empty()) out << "    {nullptr, nullptr, 0ULL},\n";
    out << "};\n";
    out << "const unsigned long long " << symbol << "Count = " << entries.size() << "ULL;\n";
    out << "} // namespace " << ns << "\n";

    const std::string text = out.str();
    std::ofstream f(outPath, std::ios::binary | std::ios::trunc);
    if (!f) {
        std::fprintf(stderr, "gt_embed: cannot write '%s'\n", outPath.c_str());
        return 1;
    }
    f << text;
    return 0;
}
